import os,json,shutil,time
m={}
for line in open('/proc/meminfo'):
 k,v=line.split(':',1)
 if k in ('MemTotal','MemAvailable','MemFree','SwapTotal','SwapFree','Cached'):
  m[k]=round(int(v.split()[0])/1048576,3)
vm={}
for line in open('/proc/vmstat'):
 k,v=line.split()
 if k in ('pswpin','pswpout'):vm[k]=int(v)
limits={}
for p in ('/sys/fs/cgroup/memory.max','/sys/fs/cgroup/memory.current','/sys/fs/cgroup/cpu.max'):
 try: limits[p.rsplit('/',1)[1]]=open(p).read().strip()
 except OSError: pass
print(json.dumps({'utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'ram_gib':m,'logical_cpus':os.cpu_count(),'load_average':os.getloadavg(),'project_disk_free_gib':round(shutil.disk_usage('/srv/projects').free/2**30,2),'cgroup':limits,'swap_counters_since_boot':vm},sort_keys=True),flush=True)
